//! `ips_viz`: library behind the rerun viewer binary.
//!
//! The binary (`src/main.rs`) subscribes to the cube poses `ips_track` publishes
//! over zenoh (`<device>/ws_ips/ips_track/zenoh/cube_poses`, custom/CubePoses),
//! fetches the camera extrinsics once from ips_track's cam_param service, and
//! streams the scene to a running rerun viewer. The tracker only publishes.

// sb-generated zenoh subscriber for `ros2/custom/CubePoses`. Do not edit, it is
// regenerated by `sb install .`. Its defaults name this module's own segment;
// main() builds the ips_track key from DEFAULT_DEVICE/DEFAULT_WORKSPACE and opens
// it with `TopicOverrides.full`. The allow is for a lint inside the generated
// `try_recv_latest` (`e.into()` on an error that is already the target type).
#[allow(clippy::useless_conversion)]
#[path = "../swarmbotix_io/subscribers/cube_poses.rs"]
pub mod cube_poses_sub;

// sb-generated iceoryx2 subscriber for `ros2/sensor_msgs/Image1280x1024Color`.
// Do not edit. iox2 has no wildcard, so main() opens one per camera, each on
// that camera's `<device>/ws_ips/ips_detect-sbNN/iox2/debug_image` via `full`.
#[path = "../swarmbotix_io/subscribers/debug_image.rs"]
pub mod debug_image_sub;

// prost types for `custom/CubePoses` and its import `custom/MarkerDetections`
// (package `swarmbotix.custom`): Vec3, Quat, Mat3, CubePose, CubePoses and the
// marker types. build.rs compiles them from ../messages.
pub mod msgs {
    include!(concat!(env!("OUT_DIR"), "/swarmbotix.custom.rs"));
}

// The parameters, the off-wire geometry (cube box, camera extrinsics) and the
// rerun view: blueprint, cameras, cubes, plots, debug images.
pub mod visualize;
